Method.Implementation:
set tSC = $$$OK
NEW $NAMESPACE
set $NAMESPACE = "DEPLOYHIST"

&sql(select ID into :nmId from Namespaces  where NameSpace = :nmSp)

if (SQLCODE = 0)
{

   	&sql(INSERT INTO Component (ComponentName, NameSpace) values ( :itemNm, :nmId ))
   	if (SQLCODE '= 0)
	{
   		set tSC = $$$ERROR("Insert to Component failed. SQLCODE: " _ SQLCODE)
	}
}
else 
{
	 set tSC = $$$ERROR("Selection of Namespace ID failed for" _ nmSp _ ". SQLCODE: " _ SQLCODE)
}
return tSC

	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("GetComponentId")
    &sql(Select c.ID INTO :compId from Component c,  Namespaces n where n.ID = c.NameSpace AND c.ComponentName = :compNm  AND n.NameSpace = :nmSp)
    IF (SQLCODE '= 0) {
	    set tSC = ..InsertComponent(compNm, nmSp)
	    if $$$ISOK(tSC)
	    {
		    set SQLCODE = 0
		    &sql(Select c.ID INTO :compId from Component c,  Namespaces n where n.ID = c.NameSpace AND c.ComponentName = :compNm  AND n.NameSpace = :nmSp )
	    }
	    if (SQLCODE '= 0) 
	    {
	    	set fault=..MakeFault($$$FAULTServer, "SQL error", "Could not get Component Id for " _ compNm _ " from .Component. SQLCODE: " _ SQLCODE)
	   		Do ..ReturnFault(fault)
	   		QUIT
	    }

    }
    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("ComponentId: " _ compId) 
    return compId

NEW $NAMESPACE set $NAMESPACE = "DEPLOYHIST" Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateComponentImpl for " _ componentNm _ " in " _ nmSp _ " Environment: " _ env) set compId = ..GetComponentId(componentNm, nmSp)
set envId = ..GetEnvironmentId(env)
&sql(INSERT INTO ComponentImpl (ComponentName, Environment, ImplFile, ImplFileVersion, ImplFileInformation, ImplementionDate, UserName ) values (:compId, :envId, :DeploymentFile, :fileVersion, :fileInfo, :dt, :usrNm ) ) if SQLCODE = 0 { Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Insert done") return $$$OK } else { set fault=..MakeFault($$$FAULTServer, "SQL error", "Insert to ComponentImpl failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE)) Do ..ReturnFault(fault) QUIT }

NEW $NAMESPACE set $NAMESPACE = "DEPLOYHIST"
&sql(INSERT INTO ITFCOMMONClasses (FileName, UserName, Instance, Revision, ImplDtTm, Description) VALUES (:cls, :usr, :inst, :rev, :dttm, :desc)) if SQLCODE = 0 { Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Insert Done") return $$$OK } else { set fault=..MakeFault($$$FAULTServer, "SQL error", "Insert to ITFCOMMONClasses failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE)) Do ..ReturnFault(fault) QUIT
}
